import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"FAQ","description":"Frequently asked questions about Pterodactyl Revamp — install paths, supported versions, the queue worker, bulk move, blade patches, and uninstall.","frontmatter":{"title":"FAQ","description":"Frequently asked questions about Pterodactyl Revamp — install paths, supported versions, the queue worker, bulk move, blade patches, and uninstall."},"headers":[],"relativePath":"pterodactyl-revamp/getting-started/faq.md","filePath":"pterodactyl-revamp/getting-started/faq.md","lastUpdated":1785513726000}'),o={name:"pterodactyl-revamp/getting-started/faq.md"};function r(i,e,l,d,h,p){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h1><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><h3 id="do-i-need-blueprint-to-use-revamp" tabindex="-1">Do I need Blueprint to use Revamp? <a class="header-anchor" href="#do-i-need-blueprint-to-use-revamp" aria-label="Permalink to &quot;Do I need Blueprint to use Revamp?&quot;">​</a></h3><p>No. Blueprint is the recommended install path, but the addon ships a <strong>standalone</strong> flavor too: merge <code>standalone/PanelFiles/</code> into your panel root and run <code>standalone/data/install.sh</code> (or apply <code>PanelEdit.txt</code> by hand). The feature set is identical either way — only the delivery mechanism differs. See <a href="/pingless-studios-docs/pterodactyl-revamp/getting-started/installation">Installation</a>.</p><h3 id="which-pterodactyl-and-php-versions-are-supported" tabindex="-1">Which Pterodactyl and PHP versions are supported? <a class="header-anchor" href="#which-pterodactyl-and-php-versions-are-supported" aria-label="Permalink to &quot;Which Pterodactyl and PHP versions are supported?&quot;">​</a></h3><p>Pterodactyl Panel <strong>1.12.x – 1.14.x</strong>, PHP <strong>8.2 / 8.3</strong>, and MySQL/MariaDB <strong>10.4+</strong>. The Blueprint package targets Blueprint <code>beta-2026-06</code>.</p><h3 id="does-revamp-work-on-pterodactyl-1-14" tabindex="-1">Does Revamp work on Pterodactyl 1.14? <a class="header-anchor" href="#does-revamp-work-on-pterodactyl-1-14" aria-label="Permalink to &quot;Does Revamp work on Pterodactyl 1.14?&quot;">​</a></h3><p>Yes. The blade patcher tries multiple anchors per injection point so it matches the blade layouts across the 1.12.x – 1.14.x range, and every injection is marker-wrapped so it can be removed cleanly. If an anchor isn&#39;t found on a heavily modified panel, the installer prints a <code>WARN: anchor not found</code> line instead of corrupting the template.</p><h3 id="does-revamp-replace-core-panel-files" tabindex="-1">Does Revamp replace core panel files? <a class="header-anchor" href="#does-revamp-replace-core-panel-files" aria-label="Permalink to &quot;Does Revamp replace core panel files?&quot;">​</a></h3><p>No. Revamp adds its own files under <code>app/</code>, <code>routes/</code>, <code>resources/</code>, and <code>database/migrations/</code>, and patches a small number of core blades by <strong>injecting marker-wrapped blocks</strong> (<code>&lt;!-- pterodactylrevamp-...-start/end --&gt;</code>). Removal scripts strip exactly those blocks and restore the original markup, so the changes are fully reversible.</p><h2 id="admin-ui" tabindex="-1">Admin UI <a class="header-anchor" href="#admin-ui" aria-label="Permalink to &quot;Admin UI&quot;">​</a></h2><h3 id="where-does-revamp-appear-in-the-admin-panel" tabindex="-1">Where does Revamp appear in the admin panel? <a class="header-anchor" href="#where-does-revamp-appear-in-the-admin-panel" aria-label="Permalink to &quot;Where does Revamp appear in the admin panel?&quot;">​</a></h3><p>The admin area lives at <strong><code>/admin/revamp</code></strong>, and on Blueprint installs it also gets a page in the <strong>Extensions hub</strong>. The installer deliberately does <strong>not</strong> inject a core admin sidebar link — if you want one on a standalone install, <code>PanelEdit.txt</code> documents the optional sidebar block for <code>resources/views/layouts/admin.blade.php</code>. Several features also surface as injected islands on existing pages, such as the port picker in <strong>Allocation Management → Default Allocation</strong> on the Create Server page.</p><h3 id="my-admin-pages-show-duplicated-content-after-reinstalling-—-why" tabindex="-1">My admin pages show duplicated content after reinstalling — why? <a class="header-anchor" href="#my-admin-pages-show-duplicated-content-after-reinstalling-—-why" aria-label="Permalink to &quot;My admin pages show duplicated content after reinstalling — why?&quot;">​</a></h3><p>Older versions of the blade patcher could stack duplicate injection blocks on repeat installs. The current patcher is idempotent (it reports <code>already present</code> on repeat runs) and strips orphaned markers before injecting. If you&#39;re seeing duplicates from an old install, heal the panel with a remove-then-install cycle:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -remove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactylrevamp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactylrevamp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> view:clear</span></span></code></pre></div><p>Hard-refresh your browser afterwards to drop cached pages.</p><h2 id="bulk-operations" tabindex="-1">Bulk Operations <a class="header-anchor" href="#bulk-operations" aria-label="Permalink to &quot;Bulk Operations&quot;">​</a></h2><h3 id="why-do-bulk-actions-say-job-is-queued-but-not-running" tabindex="-1">Why do bulk actions say &quot;Job is queued but not running&quot;? <a class="header-anchor" href="#why-do-bulk-actions-say-job-is-queued-but-not-running" aria-label="Permalink to &quot;Why do bulk actions say &quot;Job is queued but not running&quot;?&quot;">​</a></h3><p>Bulk jobs are dispatched to the <code>revamp</code> queue, so this message means nothing is consuming that queue. Start a worker that listens to it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue:work</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --queue=revamp,default</span></span></code></pre></div><p>For small panels you can instead set <code>REVAMP_BULK_SYNC=true</code> in the panel <code>.env</code> to run bulk jobs synchronously in the web request — handy for testing, not recommended for large batches.</p><h3 id="why-is-bulk-move-disabled-by-default-and-how-do-i-enable-it" tabindex="-1">Why is bulk move disabled by default, and how do I enable it? <a class="header-anchor" href="#why-is-bulk-move-disabled-by-default-and-how-do-i-enable-it" aria-label="Permalink to &quot;Why is bulk move disabled by default, and how do I enable it?&quot;">​</a></h3><p>Bulk move only <strong>re-points panel database records</strong> to another node — it does not transfer the server&#39;s data through Wings, so a naive move would leave servers broken on their old node. Because of that, the action is gated behind the <code>bulk_move_enabled</code> setting, which defaults to off.</p><div class="warning custom-block"><p class="custom-block-title">No data is transferred</p><p>Enable <strong>Admin → Revamp → Settings → bulk move</strong> only if you understand that the actual files stay on the source node. Use it for lab/testing setups or when you handle the Wings-side transfer yourself.</p></div><h2 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h2><h3 id="what-queue-worker-and-cron-do-i-need" tabindex="-1">What queue worker and cron do I need? <a class="header-anchor" href="#what-queue-worker-and-cron-do-i-need" aria-label="Permalink to &quot;What queue worker and cron do I need?&quot;">​</a></h3><p>Two standard Pterodactyl pieces: a queue worker consuming the <code>revamp</code> queue (<code>php artisan queue:work --queue=revamp,default</code>) and the scheduler running every minute via cron (<code>* * * * * php /var/www/pterodactyl/artisan schedule:run</code>). The queue drives bulk jobs; the scheduler drives metrics rollups and health snapshots.</p><h3 id="can-regular-users-see-server-tags" tabindex="-1">Can regular users see server tags? <a class="header-anchor" href="#can-regular-users-see-server-tags" aria-label="Permalink to &quot;Can regular users see server tags?&quot;">​</a></h3><p>Only if you turn it on. The <code>tags_visible_to_users</code> setting (Admin → Revamp → Tags, default off) controls whether tags are exposed to server owners through the client API endpoint <code>GET /api/client/servers/{server}/tags</code>. With the setting off, tags are an admin-only organizational tool.</p><h3 id="how-do-i-fully-uninstall-revamp-including-the-database-tables" tabindex="-1">How do I fully uninstall Revamp, including the database tables? <a class="header-anchor" href="#how-do-i-fully-uninstall-revamp-including-the-database-tables" aria-label="Permalink to &quot;How do I fully uninstall Revamp, including the database tables?&quot;">​</a></h3><ol><li>Blueprint: <code>blueprint -remove pterodactylrevamp</code>. Standalone: run <code>standalone/data/remove.sh</code> (or revert <code>PanelEdit.txt</code> manually) and delete the merged Revamp files.</li><li>Roll back the addon&#39;s migrations — every Revamp migration has a <code>down()</code> method that drops its tables — or drop the <code>revamp_*</code> tables manually.</li></ol><div class="danger custom-block"><p class="custom-block-title">Take a database backup first</p><p>Dropping the <code>revamp_*</code> tables permanently deletes settings, tags, templates, audit logs, metrics, and health history. The remove scripts intentionally leave the tables in place so an accidental removal doesn&#39;t destroy data.</p></div>`,33)])])}const m=a(o,[["render",r]]);export{u as __pageData,m as default};
